15	extern void __global_pointer$();
16	
17	pcb_t pcb[NUM_MAX_TASK];
18	pcb_t kernel_pcb[NR_CPUS];
19	const pcb_t *core0_tp = &kernel_pcb[0];
20	const pcb_t *core1_tp = &kernel_pcb[1];
21	const ptr_t kernel_stack_0 = INIT_KERNEL_STACK + PAGE_SIZE;
22	const ptr_t kernel_stack_1 = INIT_KERNEL_STACK + 2 * PAGE_SIZE;
23	
24	LIST_HEAD(ready_queue);
25	LIST_HEAD(sleep_queue);
26	
27	/* current running task PCB */
28	pcb_t * volatile current_running[NR_CPUS];
29	pcb_t * volatile current_cpu_running;
30	
31	/* global process id */
32	pid_t process_id = 2;
33	
34	static void release_resources(pcb_t *task);
35	static void reclaim_pcb(pcb_t *task);
36	
37	/*
38	 * Only modify PCB, current_running, process_id and ready_queue
39	 * DO NOT STORE OR RESTORE 
40	 * trick: modify $tp in ret_from_exception to ensure
41	 * disable_preempt() and enable_preempt() modify the same PCB
42	 */
43	void scheduler(void)
44	{
45	    pcb_t *prev = current_running[cpu_id];
46	    pcb_t *next;
47	    list_node_t *next_node;
48	
49	    if (prev != &kernel_pcb[cpu_id]) {
50	        if (prev->status == TASK_RUNNING) {
51	            /* still runnable: back to the tail of the ready queue */
52	            prev->status = TASK_READY;
53	            prev->ready_tick = get_ticks();
54	            list_add_tail(&prev->list, &ready_queue);
55	        } else if (prev->status == TASK_KILLED) {
56	            /* it was killed while running on this core; now that we are
57	             * about to leave its kernel stack the teardown can finish */
58	            reclaim_pcb(prev);
59	        }
60	    }
61	
62	    next_node = max_priority_node();
63	    if (next_node == NULL) {
64	        /* nothing this hart may run, go back to its idle task */
65	        next = &kernel_pcb[cpu_id];
66	    } else {
67	        list_del(next_node);
68	        next = list_entry(next_node, pcb_t, list);
69	    }
70	
71	    next->status = TASK_RUNNING;
72	    next->cpu_id = cpu_id;
73	    current_running[cpu_id] = next;
74	    /* ret_from_exception restores the context of `current_cpu_running` */
75	    current_cpu_running = next;
76	
77	    /* every task owns its own cursor position */
78	    screen_cursor_x[cpu_id] = next->cursor_x;
79	    screen_cursor_y[cpu_id] = next->cursor_y;
80	}
81	
82	/* Prepare the kernel stack of a brand new task so that ret_from_exception
83	 * drops it straight into `entry_point` with `arg` in a0. */
84	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
85	                           pcb_t *pcb, void *arg)
86	{
87	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
88	    pcb->kernel_sp -= sizeof(regs_context_t);
89	
90	    /* the pcb slot may have been used before, do not inherit stale registers */
91	    kmemset(pt_regs, 0, sizeof(regs_context_t));
92	
93	    /* initialization registers: ra, sp, gp, a0, sstatus, sepc, sscratch */
94	    pt_regs->regs[1] = (reg_t)entry_point;       //ra
95	    pt_regs->regs[2] = (reg_t)user_stack;        //sp
96	    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
97	    pt_regs->regs[10] = (reg_t)arg;              //a0, the argument of the task
98	    pt_regs->sepc = (reg_t)entry_point;          //sepc
99	    if (pcb->type == USER_PROCESS || pcb->type == USER_THREAD) {
100	        pt_regs->sstatus = (reg_t)SR_SPIE;       //SPP = 0, SPIE = 1
101	        pt_regs->sscratch = (reg_t)pcb;          //sscratch = tp
102	    } else {
103	        pt_regs->sstatus = (reg_t)(SR_SPP | SR_SPIE); //SPP = 1, SPIE = 1
104	        pt_regs->sscratch = (reg_t)0;
105	    }
106	}
107	
108	pid_t do_spawn(task_info_t *task, void* arg, spawn_mode_t mode)
109	{
110	    disable_preempt();
111	
112	    /* look for a free pcb: `pid == -1` marks an unused slot */
113	    int i;
114	    for (i = 0; i < NUM_MAX_TASK; i++) {
115	        if (pcb[i].pid == -1) {
116	            break;
117	        }
118	    }
119	    if (i == NUM_MAX_TASK) {
120	        enable_preempt();
121	        return -1;
122	    }
123	
124	    pcb_t *new_pcb = &pcb[i];
125	    new_pcb->kernel_sp = allocPage(1);
126	    new_pcb->user_sp = allocPage(1);
127	    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
128	    new_pcb->user_stack_base = new_pcb->user_sp;
129	    new_pcb->preempt_count = 0;
130	    init_list_head(&new_pcb->wait_list);
131	    init_list_head(&new_pcb->timer.list);
132	    new_pcb->binsem_num = 0;
133	    new_pcb->pid = process_id++;
134	    new_pcb->type = task->type;
135	    new_pcb->status = TASK_READY;
136	    new_pcb->mode = mode;
137	    new_pcb->priority = task->priority;
138	    new_pcb->ready_tick = get_ticks();
139	    /* a child may run wherever its parent was allowed to run */
140	    new_pcb->mask = current_running[cpu_id]->mask;
141	    if (new_pcb->mask == 0) {
142	        new_pcb->mask = (1UL << NR_CPUS) - 1;
143	    }
144	    new_pcb->cpu_id = cpu_id;
145	    new_pcb->cursor_x = 1;
146	    new_pcb->cursor_y = 1;
147	
148	    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp,
149	                   task->entry_point, new_pcb, arg);
150	    list_add_tail(&new_pcb->list, &ready_queue);
151	
152	    pid_t new_pid = new_pcb->pid;
153	    enable_preempt();
154	    return new_pid;
155	}
156	
157	/* Give up every binary semaphore `task` still holds and hand each of them to
158	 * the next waiter, so that nobody stays blocked on a dead process. */
159	static void release_binsem(pcb_t *task)
160	{
161	    while (task->binsem_num > 0) {
162	        int id = task->binsem_id[--task->binsem_num];
163	        binsem_node_t *node = &binsem_nodes[id];
164	
165	        node->sem++;
166	        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
167	            list_node_t *heir_node = node->block_queue.next;
168	            pcb_t *heir = list_entry(heir_node, pcb_t, list);
169	            heir->binsem_id[heir->binsem_num++] = id;
170	            do_unblock(heir_node);
171	        }
172	    }
173	}
174	
175	/* Common part of exiting and being killed: hand back the semaphores, wake
176	 * everybody who waits for this task and release the user stack. */
177	static void release_resources(pcb_t *task)
178	{
179	    release_binsem(task);
180	
181	    while (!list_empty(&task->wait_list)) {
182	        do_unblock(task->wait_list.next);
183	    }
184	
185	    /* a sleeping task may still have an armed timer */
186	    list_del(&task->timer.list);
187	
188	    freePage(task->user_stack_base, 1);
189	}
190	
191	/* Finish the teardown of a task that is no longer running anywhere. */
192	static void reclaim_pcb(pcb_t *task)
193	{
194	    list_del(&task->list);
195	
196	    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
197	        /* the parent reaps us in do_waitpid() */
198	        task->status = TASK_ZOMBIE;
199	    } else {
200	        /* the idle task of core 0 frees the kernel stack we may still be
201	         * standing on and marks the pcb slot free again */
202	        task->status = TASK_EXITED;
203	        list_add_tail(&task->list, &kernel_pcb[0].wait_list);
204	    }
205	}
206	
207	void do_exit()
208	{
209	    disable_preempt();
210	    pcb_t *cur = current_running[cpu_id];
211	
212	    /* take ourselves out of the ready queue first: the wakeups below may
213	     * call scheduler(), which must not put a dying task back */
214	    list_del(&cur->list);
215	    cur->status = TASK_EXITED;
216	
217	    release_resources(cur);
218	    reclaim_pcb(cur);
219	
220	    scheduler();
221	    enable_preempt();
222	}
223	
224	// sleep(seconds)
225	void do_sleep(uint32_t sleep_time)
226	{
227	    // 1. block the current_running
228	    // 2. create a timer which calls `do_unblock` when timeout
229	    // 3. reschedule because the current_running is blocked
230	    do_block(&current_running[cpu_id]->list, &sleep_queue);
231	    list_node_t* parameter = &current_running[cpu_id]->list;
232	    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
233	    scheduler();
234	}
235	
236	int do_kill(pid_t pid)
237	{
238	    disable_preempt();
239	
240	    pcb_t *victim = NULL;
241	    for (int i = 0; i < NUM_MAX_TASK; i++) {
242	        if (pcb[i].pid == pid) {
243	            victim = &pcb[i];
244	            break;
245	        }
246	    }
247	    if (victim == NULL || victim->status == TASK_EXITED ||
248	        victim->status == TASK_ZOMBIE || victim->status == TASK_KILLED) {
249	        enable_preempt();
250	        return 0;
251	    }
252	
253	    if (victim == current_running[cpu_id]) {
254	        /* killing ourselves is just an exit */
255	        enable_preempt();
256	        do_exit();
257	        return 1;
258	    }
259	
260	    release_resources(victim);
261	
262	    if (victim->status == TASK_RUNNING) {
263	        /* it is running on the other hart: flag it and let that hart finish
264	         * the teardown as soon as it enters the kernel again */
265	        victim->status = TASK_KILLED;
266	    } else {
267	        reclaim_pcb(victim);
268	    }
269	
270	    enable_preempt();
271	    return 1;
272	}
273	
274	/*
275	 * A blocked process can only be resumed in user mode, so waitpid cannot
276	 * simply continue where it left off.  Instead the caller is blocked on the
277	 * child's wait list and `sepc` is rewound onto the `ecall`, so once the child
278	 * exits the system call is executed again -- this time finding the child
279	 * gone (or a zombie ready to be reaped).  The return value has to be `pid`
280	 * in that case because handle_syscall() writes it back into a0, which is the
281	 * very argument the retried `ecall` will pick up.
282	 */
283	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, regs_context_t *regs)
284	{
285	    disable_preempt();
286	
287	    pcb_t *child = NULL;
288	    for (int i = 0; i < NUM_MAX_TASK; i++) {
289	        if (pcb[i].pid == pid) {
290	            child = &pcb[i];
291	            break;
292	        }
293	    }
294	
295	    if (child == NULL) {
296	        /* already gone and cleaned up */
297	        enable_preempt();
298	        return 0;
299	    }
300	
301	    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
302	        /* reap it: release the kernel stack and free the pcb slot */
303	        freePage(child->kernel_stack_base, 1);
304	        list_del(&child->list);
305	        child->status = TASK_EXITED;
306	        child->pid = -1;
307	        enable_preempt();
308	        return 1;
309	    }
310	
311	    /* still alive: sleep on it and retry the system call when woken up */
312	    regs->sepc = regs->sepc - 4;
313	    do_block(&current_running[cpu_id]->list, &child->wait_list);
314	    scheduler();
315	
316	    enable_preempt();
317	    return pid;
318	}
319	
320	void do_process_show(char* buffer)
321	{
322	    buffer[0] = '\0';
323	    kstrcat(buffer, "[PROCESS TABLE]\n");
324	    kstrcat(buffer, "INIT 0    STATUS: ");
325	    if(kernel_pcb[0].status == TASK_BLOCKED){
326	        kstrcat(buffer, "BLOCKED    MASK: ");
327	        char mask[2];
328	        kitoa(mask, kernel_pcb[0].mask);
329	        kstrcat(buffer, mask);
330	        kstrcat(buffer, "\n");
331	    }
332	    else if(kernel_pcb[0].status == TASK_RUNNING){
333	        kstrcat(buffer, "RUNNING    MASK: ");
334	        char mask[2];
