492	/*
493	 * Pick the ready task with the highest effective priority that is allowed to
494	 * run on this hart.  The effective priority is the static priority plus an
495	 * ageing bonus of one point per scheduling tick already spent waiting, so a
496	 * low priority task cannot starve.  Ties go to the task that has been in the
497	 * queue longest, which keeps equal priorities round-robin.
498	 */
499	list_node_t* max_priority_node(void)
500	{
501	    list_node_t *node;
502	    list_node_t *max_node = NULL;
503	    uint64_t max_priority = 0;
504	    uint64_t current_tick = get_ticks();
505	
506	    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
507	        pcb_t *task = list_entry(node, pcb_t, list);
508	        uint64_t waited_tick = 0;
509	        uint64_t priority;
510	
511	        /* cpu affinity */
512	        if (!(task->mask & (1UL << cpu_id))) {
513	            continue;
514	        }
515	
516	        if (current_tick > task->ready_tick) {
517	            waited_tick = current_tick - task->ready_tick;
518	        }
519	        priority = (uint64_t)task->priority;
520	        if (timer_interval != 0) {
521	            priority += waited_tick / timer_interval;
522	        }
523	
524	        if (max_node == NULL || priority > max_priority) {
525	            max_node = node;
526	            max_priority = priority;
527	        }
528	    }
529	
530	    return max_node;
531	}
