#define DIR   1
#define FILE  2
// 32 bytes
typedef struct dir_entry{
    uint8_t type;
    uint8_t name[29];
    uint16_t inode;
} dir_entry_t;
// 4096 bytes
typedef struct dir{
    dir_entry_t entry[128];
} dir_t;

